"use strict";

// The same defect in a DIFFERENT required position: an object literal's
// ordinary property VALUE.
//
//     const table = { fn: bail() };
//
// RWF-024 models an object literal's computed KEY. A property VALUE is a
// separate required position, and it is required for the same reason:
// evaluating the literal evaluates every property's value before the
// object exists, so the literal never finishes constructing.
//
// There is deliberately no `class`-shaped deferral to appeal to here. An
// object literal has no per-instance deferral for an ordinary property's
// VALUE at all (unlike a class INSTANCE field, which really is deferred --
// see `conditional.js`).
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("fast mode is not supported here");
}

function safeKey() {
  return "mode";
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // The KEY is harmless -- RWF-024's rule never fires here. The VALUE is
  // what ends module evaluation.
  const table = {
    [safeKey()]: bail(),
  };
  void table;
}

module.exports = safeOp;
